def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_last = history[-1][1]
    if opp_last == 'C':
        return 'C'
    if n >= 90:
        return 'D'
    if n >= 2 and history[-2][1] == 'D':
        return 'D'
    return 'C'
